<?php
declare(strict_types=1);

function hasAnyPermissionV14(PDO $pdo, int $userId, array $moduleCodes, string $action): bool
{
    if (isSuperAdmin($pdo, $userId)) return true;
    foreach ($moduleCodes as $moduleCode) {
        if (userHasPermission($pdo, $userId, $moduleCode, $action)) return true;
    }
    return false;
}

function requireAnyPermissionV14(PDO $pdo, int $userId, array $moduleCodes, string $action): void
{
    if (!hasAnyPermissionV14($pdo, $userId, $moduleCodes, $action)) {
        failRequest('No tienes permiso para realizar esta operación.', 403);
    }
}

function itemModuleV14(string $itemType): string
{
    return match ($itemType) {
        'RAW_FRUIT', 'RAW_OTHER', 'BULK_OIL' => 'WAREHOUSE_RAW',
        'PACKAGING', 'CONSUMABLE' => 'WAREHOUSE_PACKAGING',
        'SPARE_PART' => 'WAREHOUSE_SPARES',
        'FINISHED_GOOD' => 'WAREHOUSE_FINISHED',
        default => 'CATALOGS',
    };
}

function itemTypesForUserV14(PDO $pdo, int $userId, bool $isAdmin): array
{
    if ($isAdmin || userHasPermission($pdo,$userId,'INVENTORY','VIEW') || userHasPermission($pdo,$userId,'COUNTS','VIEW')) {
        return ['RAW_FRUIT','RAW_OTHER','BULK_OIL','PACKAGING','CONSUMABLE','SPARE_PART','FINISHED_GOOD'];
    }
    $types=[];
    if (userHasPermission($pdo,$userId,'WAREHOUSE_RAW','VIEW')) $types=array_merge($types,['RAW_FRUIT','RAW_OTHER','BULK_OIL']);
    if (userHasPermission($pdo,$userId,'WAREHOUSE_PACKAGING','VIEW')) $types[]='PACKAGING';
    if (userHasPermission($pdo,$userId,'WAREHOUSE_SPARES','VIEW')) $types[]='SPARE_PART';
    if (userHasPermission($pdo,$userId,'WAREHOUSE_FINISHED','VIEW')) $types[]='FINISHED_GOOD';
    if (hasAnyPermissionV14($pdo,$userId,['PURCHASING','APPOINTMENTS','RECEIVING'],'VIEW')) $types=array_merge($types,['RAW_FRUIT','RAW_OTHER','BULK_OIL','PACKAGING','CONSUMABLE','SPARE_PART']);
    if (userHasPermission($pdo,$userId,'QUALITY','VIEW')) $types=array_merge($types,['RAW_FRUIT','RAW_OTHER','BULK_OIL','PACKAGING','CONSUMABLE','SPARE_PART','FINISHED_GOOD']);
    if (hasAnyPermissionV14($pdo,$userId,['FILLING','PRODUCTION'],'VIEW')) $types=array_merge($types,['RAW_OTHER','BULK_OIL','PACKAGING','CONSUMABLE','FINISHED_GOOD']);
    if (userHasPermission($pdo,$userId,'EXTRACTION','VIEW')) $types=array_merge($types,['RAW_FRUIT','BULK_OIL']);
    if (hasAnyPermissionV14($pdo,$userId,['FORECAST','MRP'],'VIEW')) $types[]='FINISHED_GOOD';
    return array_values(array_unique($types));
}

function warehouseTypesForItemTypesV14(array $itemTypes): array
{
    $types=[];
    if (array_intersect($itemTypes,['RAW_FRUIT','RAW_OTHER','BULK_OIL'])) $types=array_merge($types,['RAW_MATERIAL','PROCESS']);
    if (array_intersect($itemTypes,['PACKAGING','CONSUMABLE'])) $types[]='PACKAGING';
    if (in_array('SPARE_PART',$itemTypes,true)) $types[]='SPARE_PARTS';
    if (in_array('FINISHED_GOOD',$itemTypes,true)) $types[]='FINISHED_GOODS';
    return array_values(array_unique($types));
}

function applyV14DataScope(PDO $pdo, array $user, bool $isAdmin, array &$result): void
{
    if ($isAdmin) return;
    $userId=(int)$user['id'];
    $itemTypes=itemTypesForUserV14($pdo,$userId,false);
    $warehouseTypes=warehouseTypesForItemTypesV14($itemTypes);
    if (userHasPermission($pdo,$userId,'QUALITY','VIEW')) $warehouseTypes=array_values(array_unique(array_merge($warehouseTypes,['QUARANTINE','REJECTED','RETURNS'])));
    $itemAllowed=static fn(array $row): bool=>in_array((string)($row['item_type']??$row['type']??''),$itemTypes,true);
    $warehouseAllowed=static fn(array $row): bool=>in_array((string)($row['warehouse_type']??''),$warehouseTypes,true);
    foreach (['items'] as $key) if(isset($result['lookups'][$key])) $result['lookups'][$key]=array_values(array_filter($result['lookups'][$key],$itemAllowed));
    if(isset($result['lookups']['finishedGoods'])&&!in_array('FINISHED_GOOD',$itemTypes,true)) $result['lookups']['finishedGoods']=[];
    foreach (['warehouses','locationsV14'] as $key) if(isset($result['lookups'][$key])) $result['lookups'][$key]=array_values(array_filter($result['lookups'][$key],$warehouseAllowed));
    if(isset($result['lookups']['locations'])){
        $allowedWarehouseIds=array_map(static fn(array $row)=>(int)$row['id'],$result['lookups']['warehouses']??[]);
        $result['lookups']['locations']=array_values(array_filter($result['lookups']['locations'],static fn(array $row): bool=>in_array((int)$row['warehouse_id'],$allowedWarehouseIds,true)));
    }
    foreach (['openAppointmentLines','availableLots'] as $key) if(isset($result['lookups'][$key])) $result['lookups'][$key]=array_values(array_filter($result['lookups'][$key],$itemAllowed));

    $warehouseItemTypes=[];
    if (userHasPermission($pdo,$userId,'INVENTORY','VIEW')) $warehouseItemTypes=['RAW_FRUIT','RAW_OTHER','BULK_OIL','PACKAGING','CONSUMABLE','SPARE_PART','FINISHED_GOOD'];
    if (userHasPermission($pdo,$userId,'WAREHOUSE_RAW','VIEW')) $warehouseItemTypes=array_merge($warehouseItemTypes,['RAW_FRUIT','RAW_OTHER','BULK_OIL']);
    if (userHasPermission($pdo,$userId,'WAREHOUSE_PACKAGING','VIEW')) $warehouseItemTypes[]='PACKAGING';
    if (userHasPermission($pdo,$userId,'WAREHOUSE_SPARES','VIEW')) $warehouseItemTypes[]='SPARE_PART';
    if (userHasPermission($pdo,$userId,'WAREHOUSE_FINISHED','VIEW')) $warehouseItemTypes[]='FINISHED_GOOD';
    $warehouseItemTypes=array_values(array_unique($warehouseItemTypes));
    $warehouseAccessTypes=warehouseTypesForItemTypesV14($warehouseItemTypes);
    $warehouseAccessTypes=array_values(array_filter($warehouseAccessTypes,static fn(string $type): bool=>$type!=='PROCESS'));
    if(isset($result['warehouseInventory']))$result['warehouseInventory']=array_values(array_filter($result['warehouseInventory'],static fn(array $row): bool=>in_array((string)$row['type'],$warehouseItemTypes,true)));
    if(isset($result['inboundExpected'])&&!hasAnyPermissionV14($pdo,$userId,['PURCHASING','APPOINTMENTS'],'VIEW'))$result['inboundExpected']=array_values(array_filter($result['inboundExpected'],static fn(array $row): bool=>in_array((string)($row['item_type']??''),$warehouseItemTypes,true)));
    if(!userHasPermission($pdo,$userId,'COUNTS','VIEW'))foreach(['counts','auditSchedules','inventoryAuditDetails','initialInventory'] as $key)if(isset($result[$key]))$result[$key]=array_values(array_filter($result[$key],static fn(array $row): bool=>in_array((string)($row['warehouseType']??''),$warehouseAccessTypes,true)));
    if(isset($result['areaDashboard']['inventoryByWarehouse']))$result['areaDashboard']['inventoryByWarehouse']=array_values(array_filter($result['areaDashboard']['inventoryByWarehouse'],static fn(array $row): bool=>in_array((string)($row['warehouseType']??''),$warehouseAccessTypes,true)));
    foreach(['criticalMaterials','highFlow','planShortages','forecastCompliance'] as $key)if(isset($result['areaDashboard'][$key]))$result['areaDashboard'][$key]=array_values(array_filter($result['areaDashboard'][$key],$itemAllowed));
    $areaCode=(string)safeScalar($pdo,"SELECT code FROM areas WHERE id=:area",['area'=>$user['primary_area_id']]);
    if($areaCode==='ALMACEN'){
        $inventoryRows=$result['warehouseInventory']??[];$itemIds=array_values(array_unique(array_map(static fn(array $row): int=>(int)($row['itemId']??0),$inventoryRows)));
        $result['areaDashboard']['metrics']=[
            ['label'=>'Productos con existencia','value'=>count(array_filter($itemIds)),'note'=>'Sólo de los almacenes autorizados','tone'=>''],
            ['label'=>'Materiales críticos','value'=>count($result['areaDashboard']['criticalMaterials']??[]),'note'=>'Dentro de tus módulos','tone'=>'danger'],
            ['label'=>'Faltantes del plan','value'=>count($result['areaDashboard']['planShortages']??[]),'note'=>'Según el último cálculo','tone'=>'warning'],
            ['label'=>'Auditorías registradas','value'=>count($result['counts']??[]),'note'=>'Dentro de tus almacenes','tone'=>''],
        ];
    }
}

function reservePrelotV14(PDO $pdo, array $line, int $appointmentId, string $date, int $userId): array
{
    $sequence=$pdo->prepare("INSERT INTO prelot_sequences (supplier_id,origin_id,lot_date,next_value) VALUES (:supplier,:origin,:date,LAST_INSERT_ID(1)) ON DUPLICATE KEY UPDATE next_value=LAST_INSERT_ID(next_value+1)");
    $sequence->execute(['supplier'=>$line['supplier_id'],'origin'=>$line['origin_id'],'date'=>$date]);
    $seq=(int)$pdo->lastInsertId();
    $supplierCode=strtoupper(substr(preg_replace('/[^A-Z0-9]/','',(string)$line['short_code']),0,3));
    $supplierCode=str_pad($supplierCode,3,'0');
    $base=$line['item_type']==='RAW_FRUIT'?'AA'.$supplierCode.'-'.date('dmy',strtotime($date)):strtoupper($supplierCode.'-'.substr((string)$line['origin_code'],0,8).'-'.date('dmy',strtotime($date)));
    $code=$base.'-'.str_pad((string)$seq,3,'0',STR_PAD_LEFT);
    $expectedWeight=$line['item_type']==='RAW_FRUIT'?($line['expected_qty']??null):null;
    $pdo->prepare("INSERT INTO pre_lots (prelot_code,supplier_id,origin_id,appointment_id,planned_arrival_date,daily_sequence,expected_weight_kg,status,created_by) VALUES (:code,:supplier,:origin,:appointment,:date,:sequence,:expected,'PLANNED',:user)")->execute(['code'=>$code,'supplier'=>$line['supplier_id'],'origin'=>$line['origin_id'],'appointment'=>$appointmentId,'date'=>$date,'sequence'=>$seq,'expected'=>$expectedWeight,'user'=>$userId]);
    return ['id'=>(int)$pdo->lastInsertId(),'code'=>$code];
}

function buildV14Lookups(PDO $pdo, array $user, bool $isAdmin): array
{
    $userId=(int)$user['id'];
    $canWarehouse=$isAdmin||hasAnyPermissionV14($pdo,$userId,['WAREHOUSE_RAW','WAREHOUSE_PACKAGING','WAREHOUSE_SPARES','WAREHOUSE_FINISHED','INVENTORY','RECEIVING'],'VIEW');
    $canPurchase=$isAdmin||hasAnyPermissionV14($pdo,$userId,['PURCHASING','APPOINTMENTS'],'VIEW');
    $canQuality=$isAdmin||userHasPermission($pdo,$userId,'QUALITY','VIEW');
    $canFilling=$isAdmin||hasAnyPermissionV14($pdo,$userId,['FILLING','PRODUCTION'],'VIEW');
    $canExtraction=$isAdmin||userHasPermission($pdo,$userId,'EXTRACTION','VIEW');
    $canMaintenance=$isAdmin||userHasPermission($pdo,$userId,'MAINTENANCE','VIEW');
    return [
        'locationsV14'=>$canWarehouse||$canQuality||$canFilling||$canExtraction?safeRows($pdo,"SELECT l.id,l.warehouse_id,l.code,l.name,l.location_type,l.is_blocked,w.code AS warehouse_code,w.name AS warehouse_name,w.warehouse_type FROM warehouse_locations l INNER JOIN warehouses w ON w.id=l.warehouse_id WHERE l.is_active=1 AND w.is_active=1 AND w.code NOT LIKE 'EJ-%' ORDER BY w.name,l.name"):[],
        'origins'=>$canPurchase||$canWarehouse?safeRows($pdo,"SELECT o.id,o.supplier_id,o.origin_code,o.origin_name,s.supplier_code,COALESCE(s.trade_name,s.legal_name) AS supplier_name FROM supplier_origins o INNER JOIN suppliers s ON s.id=o.supplier_id WHERE o.is_active=1 AND s.is_active=1 ORDER BY supplier_name,o.origin_name"):[],
        'openAppointmentLines'=>$canWarehouse?safeRows($pdo,"SELECT al.id,al.appointment_id,a.appointment_number,a.supplier_id,a.origin_id,s.supplier_code,COALESCE(s.trade_name,s.legal_name) AS supplier_name,COALESCE(o.origin_code,'') AS origin_code,al.item_id,i.sku,i.name AS item_name,i.item_type,i.base_uom_id,u.code AS uom_code,al.destination_warehouse_id,w.name AS warehouse_name,al.expected_qty,al.received_qty,GREATEST(al.expected_qty-al.received_qty,0) AS pending_qty,DATE_FORMAT(a.scheduled_start,'%d/%m/%Y %H:%i') AS scheduled FROM inbound_appointment_lines al INNER JOIN inbound_appointments a ON a.id=al.appointment_id INNER JOIN suppliers s ON s.id=a.supplier_id LEFT JOIN supplier_origins o ON o.id=a.origin_id INNER JOIN items i ON i.id=al.item_id INNER JOIN units_of_measure u ON u.id=al.uom_id INNER JOIN warehouses w ON w.id=al.destination_warehouse_id WHERE al.line_status IN ('EXPECTED','PARTIALLY_RECEIVED') AND a.status NOT IN ('COMPLETED','CANCELLED','NO_SHOW') ORDER BY a.scheduled_start,al.line_no"):[],
        'availableLots'=>$canWarehouse||$canFilling||$canExtraction?safeRows($pdo,"SELECT a.item_id,a.inventory_lot_id,a.warehouse_id,a.location_id,a.uom_id,i.sku,i.name AS item_name,i.item_type,l.lot_code,w.name AS warehouse_name,wl.name AS location_name,u.code AS uom_code,a.available_qty FROM vw_inventory_availability a INNER JOIN items i ON i.id=a.item_id INNER JOIN inventory_lots l ON l.id=a.inventory_lot_id INNER JOIN warehouses w ON w.id=a.warehouse_id INNER JOIN warehouse_locations wl ON wl.id=a.location_id INNER JOIN units_of_measure u ON u.id=a.uom_id WHERE a.available_qty>0 AND l.quality_status IN ('APPROVED','CONDITIONAL') AND l.lot_status='OPEN' ORDER BY i.name,l.received_date,l.created_at"):[],
        'qualityRequestsV14'=>$canQuality?safeRows($pdo,"SELECT q.id AS request_id,q.request_number,q.request_type,q.inventory_lot_id,q.target_type,q.target_id,q.status,i.id AS item_id,i.name AS item_name,i.item_type,l.lot_code,COALESCE(rl.received_qty,pc.completed_qty,0) AS received_qty,COALESCE(rl.uom_id,i.base_uom_id) AS uom_id,u.code AS uom_code,COALESCE(r.warehouse_id,pcl.warehouse_id) AS warehouse_id,COALESCE(r.receipt_number,pc.completion_number,q.target_type) AS source_reference FROM quality_requests q LEFT JOIN goods_receipt_lines rl ON rl.id=q.receipt_line_id LEFT JOIN goods_receipts r ON r.id=rl.receipt_id LEFT JOIN production_completions pc ON q.target_type='PRODUCTION_COMPLETION' AND pc.id=q.target_id LEFT JOIN warehouse_locations pcl ON pcl.id=pc.output_location_id INNER JOIN inventory_lots l ON l.id=q.inventory_lot_id INNER JOIN items i ON i.id=l.item_id LEFT JOIN units_of_measure u ON u.id=COALESCE(rl.uom_id,i.base_uom_id) WHERE q.status NOT IN ('COMPLETED','CANCELLED') ORDER BY q.requested_at"):[],
        'bomVersions'=>$canFilling?safeRows($pdo,"SELECT bv.id,b.bom_code,b.name,b.output_item_id,i.sku AS output_sku,i.name AS output_name,bv.version_no,bv.output_qty,u.code AS output_uom FROM bom_versions bv INNER JOIN bills_of_material b ON b.id=bv.bom_id INNER JOIN items i ON i.id=b.output_item_id INNER JOIN units_of_measure u ON u.id=bv.output_uom_id WHERE b.is_active=1 AND bv.status='ACTIVE' ORDER BY i.name,bv.version_no DESC"):[],
        'productionOrdersV14'=>$canFilling||hasAnyPermissionV14($pdo,$userId,['WAREHOUSE_FINISHED'],'VIEW')?safeRows($pdo,"SELECT o.id,o.order_number,o.finished_item_id,o.bom_version_id,b.bom_code,i.name AS item_name,i.sku,o.planned_qty,o.completed_qty,(o.planned_qty-o.completed_qty) AS pending_qty,u.code AS uom_code,o.status FROM production_orders o INNER JOIN items i ON i.id=o.finished_item_id INNER JOIN units_of_measure u ON u.id=o.uom_id INNER JOIN bom_versions bv ON bv.id=o.bom_version_id INNER JOIN bills_of_material b ON b.id=bv.bom_id WHERE o.status NOT IN ('CLOSED','CANCELLED','COMPLETED') ORDER BY o.planned_start"):[],
        'maintenanceUsers'=>$canMaintenance&&($isAdmin||isMaintenanceLeader($pdo,$user))?safeRows($pdo,"SELECT u.id,u.display_name AS name,u.email FROM app_users u INNER JOIN areas a ON a.id=u.primary_area_id WHERE a.code='MANTENIMIENTO' AND u.status='ACTIVE' ORDER BY u.display_name"):[],
    ];
}

function buildV14Bootstrap(PDO $pdo, array $user, bool $isAdmin): array
{
    $userId=(int)$user['id'];
    $canQuality=$isAdmin||userHasPermission($pdo,$userId,'QUALITY','VIEW');
    $canFilling=$isAdmin||hasAnyPermissionV14($pdo,$userId,['FILLING','PRODUCTION'],'VIEW');
    $canExtraction=$isAdmin||userHasPermission($pdo,$userId,'EXTRACTION','VIEW');
    $canPurchase=$isAdmin||hasAnyPermissionV14($pdo,$userId,['PURCHASING','APPOINTMENTS'],'VIEW');
    $canWarehouse=$isAdmin||hasAnyPermissionV14($pdo,$userId,['WAREHOUSE_RAW','WAREHOUSE_PACKAGING','WAREHOUSE_SPARES','WAREHOUSE_FINISHED','INVENTORY'],'VIEW');
    return [
        'warehouseInventory'=>$canWarehouse?safeRows($pdo,"SELECT i.id AS itemId,i.sku,i.name AS item,i.item_type AS type,w.id AS warehouseId,w.name AS warehouse,COALESCE(l.lot_code,'Sin lote') AS lot,a.on_hand_qty AS onHand,a.available_qty AS available,u.code AS uom,CASE WHEN a.available_qty<=0 THEN 'Sin disponible' WHEN a.available_qty<=i.reorder_point THEN 'Crítico' ELSE 'Disponible' END AS status FROM vw_inventory_availability a INNER JOIN items i ON i.id=a.item_id INNER JOIN warehouses w ON w.id=a.warehouse_id INNER JOIN units_of_measure u ON u.id=a.uom_id LEFT JOIN inventory_lots l ON l.id=a.inventory_lot_id WHERE i.is_active=1 AND w.is_active=1 AND i.sku NOT LIKE 'EJ-%' AND w.code NOT LIKE 'EJ-%' ORDER BY FIELD(i.item_type,'RAW_FRUIT','RAW_OTHER','BULK_OIL','PACKAGING','SPARE_PART','FINISHED_GOOD'),i.name,l.lot_code"):[],
        'inboundExpected'=>$canPurchase||$canWarehouse?safeRows($pdo,"SELECT a.appointment_number AS appointment,COALESCE(p.prelot_code,'Pendiente de asignar') AS prelot,DATE_FORMAT(a.scheduled_start,'%d %b %Y · %H:%i') AS scheduled,COALESCE(s.trade_name,s.legal_name) AS supplier,i.name AS item,i.sku,i.item_type,w.name AS warehouse,al.expected_qty,al.received_qty,GREATEST(al.expected_qty-al.received_qty,0) AS pending_qty,u.name AS uom,al.line_status AS status FROM inbound_appointment_lines al INNER JOIN inbound_appointments a ON a.id=al.appointment_id INNER JOIN suppliers s ON s.id=a.supplier_id INNER JOIN items i ON i.id=al.item_id INNER JOIN warehouses w ON w.id=al.destination_warehouse_id INNER JOIN units_of_measure u ON u.id=al.uom_id LEFT JOIN pre_lots p ON p.appointment_id=a.id AND p.status<>'CANCELLED' WHERE al.line_status<>'CANCELLED' ORDER BY a.scheduled_start DESC LIMIT 500"):[],
        'bomCatalog'=>$canFilling||hasAnyPermissionV14($pdo,$userId,['WAREHOUSE_FINISHED'],'VIEW')?safeRows($pdo,"SELECT bv.id AS versionId,b.bom_code AS bomCode,b.name AS bomName,i.name AS product,i.sku AS productSku,bv.version_no AS versionNo,bv.output_qty AS outputQty,uo.name AS outputUom,c.id AS componentId,c.component_item_id AS componentItemId,ci.name AS component,ci.sku AS componentSku,c.qty_per_output AS componentQty,uc.name AS componentUom,c.scrap_pct AS scrapPct FROM bom_versions bv INNER JOIN bills_of_material b ON b.id=bv.bom_id INNER JOIN items i ON i.id=b.output_item_id INNER JOIN units_of_measure uo ON uo.id=bv.output_uom_id LEFT JOIN bom_components c ON c.bom_version_id=bv.id LEFT JOIN items ci ON ci.id=c.component_item_id LEFT JOIN units_of_measure uc ON uc.id=c.component_uom_id WHERE b.is_active=1 AND bv.status='ACTIVE' ORDER BY i.name,c.line_no"):[],
        'bomAvailability'=>$canFilling?safeRows($pdo,"SELECT i.id AS itemId,COALESCE(SUM(v.available_qty),0) AS availableQty FROM items i LEFT JOIN vw_inventory_availability v ON v.item_id=i.id WHERE i.is_active=1 GROUP BY i.id"):[],
        'production'=>$canFilling||hasAnyPermissionV14($pdo,$userId,['WAREHOUSE_FINISHED'],'VIEW')?safeRows($pdo,"SELECT o.id AS internalId,o.order_number AS id,i.name AS item,i.sku,COALESCE(c.trade_name,c.legal_name,'Sin cliente') AS customer,CONCAT(o.planned_qty,' ',u.code) AS planned,CONCAT(o.completed_qty,' ',u.code) AS completed,CONCAT(DATE_FORMAT(o.planned_start,'%d %b'),'–',DATE_FORMAT(o.planned_end,'%d %b')) AS date,CASE WHEN o.status IN ('MATERIAL_CHECK','ON_HOLD') THEN 'Material incompleto' ELSE 'Material disponible' END AS material,o.status,b.bom_code AS bomCode FROM production_orders o INNER JOIN items i ON i.id=o.finished_item_id INNER JOIN units_of_measure u ON u.id=o.uom_id LEFT JOIN customers c ON c.id=o.customer_id LEFT JOIN bom_versions bv ON bv.id=o.bom_version_id LEFT JOIN bills_of_material b ON b.id=bv.bom_id ORDER BY o.planned_start DESC LIMIT 500"):[],
        'productionCompletions'=>$canFilling||hasAnyPermissionV14($pdo,$userId,['WAREHOUSE_FINISHED'],'VIEW')?safeRows($pdo,"SELECT pc.completion_number AS number,o.order_number AS productionOrder,i.name AS item,l.lot_code AS lot,pc.completed_qty,u.name AS uom,pc.observations,DATE_FORMAT(pc.completed_at,'%d %b %Y · %H:%i') AS completedAt,COALESCE(usr.display_name,'Sistema') AS completedBy FROM production_completions pc INNER JOIN production_orders o ON o.id=pc.production_order_id INNER JOIN inventory_lots l ON l.id=pc.finished_lot_id INNER JOIN items i ON i.id=l.item_id INNER JOIN units_of_measure u ON u.id=i.base_uom_id LEFT JOIN app_users usr ON usr.id=pc.completed_by ORDER BY pc.completed_at DESC LIMIT 500"):[],
        'extractionRuns'=>$canExtraction||$canQuality?safeRows($pdo,"SELECT pb.id,pb.batch_code AS batchCode,DATE_FORMAT(pb.started_at,'%d %b %Y · %H:%i') AS startedAt,pb.shift_code AS shift,pb.actual_beans AS beans,pb.target_beans_hour AS targetBeansHour,ROUND(pb.actual_beans/er.operating_hours,2) AS actualBeansHour,sourceLot.lot_code AS sourceLot,sourceItem.name AS sourceItem,outputLot.lot_code AS outputLot,outputItem.name AS outputItem,q.request_number AS qualityRequest,q.status AS qualityStatus,pb.status FROM extraction_runs er INNER JOIN process_batches pb ON pb.id=er.process_batch_id INNER JOIN process_batch_inputs pbi ON pbi.process_batch_id=pb.id INNER JOIN inventory_lots sourceLot ON sourceLot.id=pbi.inventory_lot_id INNER JOIN items sourceItem ON sourceItem.id=pbi.item_id INNER JOIN inventory_lots outputLot ON outputLot.id=er.output_lot_id INNER JOIN items outputItem ON outputItem.id=outputLot.item_id LEFT JOIN quality_requests q ON q.target_type='EXTRACTION_BATCH' AND q.target_id=pb.id ORDER BY pb.started_at DESC LIMIT 500"):[],
        'rawQualityMaster'=>$canQuality?safeRows($pdo,"SELECT q.request_number AS requestNumber,l.lot_code AS lot,i.name AS item,r.week_number AS weekNumber,r.sample_date AS sampleDate,r.quantity_kg AS quantityKg,r.dry_matter_equipment_pct AS dryMatterEquipmentPct,r.dry_matter_avocado_pulp_pct AS dryMatterAvocadoPulpPct,r.dry_matter_pulp_method_pct AS dryMatterPulpMethodPct,r.firmness_pa AS firmnessPa,r.avocado_yield_soxhlet_pct AS avocadoYieldSoxhletPct,r.pulp_yield_soxhlet_pct AS pulpYieldSoxhletPct,r.free_fatty_acids_pct AS freeFattyAcidsPct,r.fruit_status AS fruitStatus,r.process_end_date AS processEndDate,r.extracted_oil_qty AS extractedOilQty,r.acidity_pct AS acidityPct,r.observations,q.disposition FROM raw_material_quality_results r INNER JOIN quality_requests q ON q.id=r.quality_request_id LEFT JOIN inventory_lots l ON l.id=q.inventory_lot_id LEFT JOIN items i ON i.id=l.item_id ORDER BY r.sample_date DESC,r.id DESC"):[],
        'extractionQualityMaster'=>$canQuality||$canExtraction?safeRows($pdo,"SELECT q.request_number AS requestNumber,pb.batch_code AS processLot,r.sample_lot_code AS sampleLot,r.week_number AS weekNumber,r.sample_date AS sampleDate,r.shift_code AS shift,r.equipment_code AS equipment,r.sample_type AS sampleType,r.fruit_per_shift_kg AS fruitPerShiftKg,r.grinding_against_target_pct AS grindingAgainstTargetPct,r.oil_wet_basis_pct AS oilWetBasisPct,r.oil_dry_basis_pct AS oilDryBasisPct,r.oil_in_fruit_pulp_pct AS oilInFruitPulpPct,r.retained_oil_pct AS retainedOilPct,r.obtaining_against_target_pct AS obtainingAgainstTargetPct,r.oil_obtained_qty AS oilObtainedQty,r.dry_matter_pct AS dryMatterPct,r.humidity_pct AS humidityPct,r.humidity_plus_dry_matter_pct AS humidityPlusDryMatterPct,r.observations,q.disposition FROM extraction_quality_results r INNER JOIN quality_requests q ON q.id=r.quality_request_id INNER JOIN process_batches pb ON pb.id=r.process_batch_id ORDER BY r.sample_date DESC,r.id DESC"):[],
        'lotMaster'=>$canQuality||$canExtraction?safeRows($pdo,"SELECT l.lot_code AS lot,i.sku,i.name AS item,l.quality_status AS qualityStatus,l.lot_status AS lotStatus,COALESCE(s.trade_name,s.legal_name,'Proceso interno') AS supplier,COALESCE(o.origin_name,'Oleolab') AS origin,DATE_FORMAT(l.created_at,'%d %b %Y · %H:%i') AS createdAt,COALESCE(GROUP_CONCAT(DISTINCT parent.lot_code ORDER BY parent.lot_code SEPARATOR ', '),'Lote de origen') AS parentLots FROM inventory_lots l INNER JOIN items i ON i.id=l.item_id LEFT JOIN suppliers s ON s.id=l.supplier_id LEFT JOIN supplier_origins o ON o.id=l.origin_id LEFT JOIN lot_relations rel ON rel.child_lot_id=l.id LEFT JOIN inventory_lots parent ON parent.id=rel.parent_lot_id GROUP BY l.id,l.lot_code,i.sku,i.name,l.quality_status,l.lot_status,s.trade_name,s.legal_name,o.origin_name,l.created_at ORDER BY l.created_at DESC LIMIT 3000"):[],
    ];
}

function createAreaItemV14(PDO $pdo, array $user, array $payload): array
{
    requireArea($pdo,$user,['ALMACEN']);
    $type=strtoupper(requiredString($payload,'item_type','el tipo de producto o material',30));
    $allowed=['RAW_FRUIT','RAW_OTHER','BULK_OIL','PACKAGING','SPARE_PART','FINISHED_GOOD'];
    if(!in_array($type,$allowed,true))failRequest('El tipo de producto o material no es válido.',422);
    requireAnyPermissionV14($pdo,(int)$user['id'],[itemModuleV14($type),'CATALOGS'],'CREATE');
    $uomCode=strtoupper(requiredString($payload,'uom_code','la unidad de medida',20));
    if($type==='RAW_FRUIT'&&$uomCode!=='KG')failRequest('El aguacate en fruta únicamente se registra en kilogramos.',422);
    if(in_array($type,['RAW_OTHER','BULK_OIL'],true)&&!in_array($uomCode,['KG','L'],true))failRequest('El aceite y las demás materias primas únicamente se registran en kilogramos o litros.',422);
    if($type==='PACKAGING'&&!in_array($uomCode,['EA','BOX','PALLET','KG','L','ROLL','BAG','DRUM'],true))failRequest('Selecciona una unidad válida para materiales de empaque.',422);
    if($type==='SPARE_PART'&&!in_array($uomCode,['EA','BOX','PALLET','KG','L'],true))failRequest('Selecciona una unidad válida para refacciones.',422);
    $categoryCode=match($type){'RAW_FRUIT'=>'FRUIT','RAW_OTHER'=>'RAW','BULK_OIL'=>'BULK','PACKAGING'=>'PACK','CONSUMABLE'=>'CONSUM','SPARE_PART'=>'SPARE','FINISHED_GOOD'=>'FG'};
    $category=findOne($pdo,"SELECT id FROM item_categories WHERE code=:category AND is_active=1",['category'=>$categoryCode],'Falta la categoría base correspondiente.');
    $uom=findOne($pdo,"SELECT id FROM units_of_measure WHERE code=:uom",['uom'=>$uomCode],'La unidad de medida no existe.');
    $sku=masterCode($payload,'sku','el código',80);
    if(safeScalar($pdo,"SELECT COUNT(*) FROM items WHERE sku=:sku",['sku'=>$sku])>0)failRequest('Ese código ya existe.',409);
    $itemName=requiredString($payload,'item_name','el nombre',190);$plainName=strtoupper(trim((string)preg_replace('/\s+/',' ',iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$itemName)?:$itemName)));
    if($type==='PACKAGING'&&preg_match('/^(AGUACATE|FRUTA|ACEITE(?: CRUDO| REFINADO)?|MATERIA PRIMA)$/',$plainName))failRequest('Ese nombre corresponde a materia prima. Regístralo únicamente desde Materia prima y aceites.',422);
    $reorder=filter_var($payload['reorder_point']??0,FILTER_VALIDATE_FLOAT);if($reorder===false||$reorder<0)failRequest('El punto de reorden no es válido.',422);
    $quality=in_array($type,['RAW_FRUIT','RAW_OTHER','BULK_OIL','PACKAGING','FINISHED_GOOD'],true)?1:0;
    $lot=in_array($type,['SPARE_PART','CONSUMABLE'],true)?0:1;
    $pdo->prepare("INSERT INTO items (category_id,base_uom_id,sku,name,item_type,lot_controlled,quality_required,reorder_point,created_by) VALUES (:category,:uom,:sku,:name,:type,:lot,:quality,:reorder,:user)")->execute(['category'=>$category['id'],'uom'=>$uom['id'],'sku'=>$sku,'name'=>$itemName,'type'=>$type,'lot'=>$lot,'quality'=>$quality,'reorder'=>$reorder,'user'=>$user['id']]);
    $id=(int)$pdo->lastInsertId();writeAudit($pdo,(int)$user['id'],'CREATE','item',$id,['sku'=>$sku,'type'=>$type,'module'=>itemModuleV14($type)]);return ['id'=>$id,'code'=>$sku];
}

function createAppointmentV14(PDO $pdo, array $user, array $payload): array
{
    requireArea($pdo,$user,['COMPRAS']);requireAnyPermissionV14($pdo,(int)$user['id'],['PURCHASING','APPOINTMENTS'],'CREATE');
    $supplier=findOne($pdo,"SELECT id,short_code FROM suppliers WHERE id=:supplier AND is_active=1",['supplier'=>(int)($payload['supplier_id']??0)],'Selecciona un proveedor válido.');
    $origin=findOne($pdo,"SELECT id,origin_code FROM supplier_origins WHERE id=:origin AND supplier_id=:supplier AND is_active=1",['origin'=>(int)($payload['origin_id']??0),'supplier'=>$supplier['id']],'Selecciona un origen válido de ese proveedor.');
    $item=findOne($pdo,"SELECT id,item_type,base_uom_id FROM items WHERE id=:item AND is_active=1",['item'=>(int)($payload['item_id']??0)],'Selecciona un material válido.');
    $warehouse=findOne($pdo,"SELECT id,warehouse_type FROM warehouses WHERE id=:warehouse AND is_active=1",['warehouse'=>(int)($payload['warehouse_id']??0)],'Selecciona el almacén destino.');
    $typeMap=['RAW_FRUIT'=>'RAW_MATERIAL','RAW_OTHER'=>'RAW_MATERIAL','BULK_OIL'=>'RAW_MATERIAL','PACKAGING'=>'PACKAGING','CONSUMABLE'=>'PACKAGING','SPARE_PART'=>'SPARE_PARTS'];
    if(($typeMap[$item['item_type']]??'')!==$warehouse['warehouse_type'])failRequest('El almacén destino no corresponde al tipo de material.',422);
    $qty=positiveNumber($payload,'expected_qty','La cantidad esperada');
    try{$start=new DateTimeImmutable(requiredString($payload,'scheduled_at','la fecha y hora'),new DateTimeZone('America/Mexico_City'));}catch(Throwable){failRequest('La fecha y hora no son válidas.',422);}
    $duration=max(15,min(480,(int)($payload['duration']??60)));$end=$start->modify("+{$duration} minutes");
    $delivery=strtoupper((string)($payload['delivery_type']??'SUPPLIER_DELIVERY'));if(!in_array($delivery,['COLLECTION','SUPPLIER_DELIVERY','TRANSFER','RETURN','OTHER'],true))failRequest('El tipo de llegada no es válido.',422);
    $expectedType=in_array($item['item_type'],['RAW_FRUIT','RAW_OTHER','PACKAGING','SPARE_PART','CONSUMABLE'],true)?$item['item_type']:($item['item_type']==='BULK_OIL'?'RAW_OTHER':'MIXED');
    $pdo->beginTransaction();
    try{
        $pdo->prepare("INSERT INTO inbound_appointments (appointment_number,supplier_id,origin_id,delivery_type,scheduled_start,scheduled_end,expected_item_type,expected_weight_kg,status,notes,created_by) VALUES (:number,:supplier,:origin,:delivery,:start,:end,:item_type,:weight,'PLANNED',:notes,:user)")->execute(['number'=>provisionalNumber('CIT'),'supplier'=>$supplier['id'],'origin'=>$origin['id'],'delivery'=>$delivery,'start'=>$start->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s'),'end'=>$end->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s'),'item_type'=>$expectedType,'weight'=>in_array($item['item_type'],['RAW_FRUIT','RAW_OTHER'],true)?$qty:null,'notes'=>optionalString($payload,'notes',1000),'user'=>$user['id']]);
        $id=(int)$pdo->lastInsertId();$number=finalNumber('CIT',$id);$pdo->prepare("UPDATE inbound_appointments SET appointment_number=:number WHERE id=:id")->execute(['number'=>$number,'id'=>$id]);
        $pdo->prepare("INSERT INTO inbound_appointment_lines (appointment_id,line_no,item_id,destination_warehouse_id,uom_id,expected_qty,notes) VALUES (:appointment,1,:item,:warehouse,:uom,:qty,:notes)")->execute(['appointment'=>$id,'item'=>$item['id'],'warehouse'=>$warehouse['id'],'uom'=>$item['base_uom_id'],'qty'=>$qty,'notes'=>optionalString($payload,'notes',500)]);
        $prelot=reservePrelotV14($pdo,['supplier_id'=>$supplier['id'],'origin_id'=>$origin['id'],'short_code'=>$supplier['short_code'],'origin_code'=>$origin['origin_code'],'item_type'=>$item['item_type'],'expected_qty'=>$qty],$id,$start->format('Y-m-d'),(int)$user['id']);
        writeAudit($pdo,(int)$user['id'],'CREATE','inbound_appointment',$id,['appointment_number'=>$number,'prelot'=>$prelot['code'],'wid_status'=>'EXPECTED','item_id'=>$item['id'],'expected_qty'=>$qty]);$pdo->commit();return ['id'=>$id,'number'=>$number,'prelot'=>$prelot['code'],'wid'=>'Esperado en WID'];
    }catch(Throwable $error){if($pdo->inTransaction())$pdo->rollBack();throw $error;}
}

function createReceiptV14(PDO $pdo, array $user, array $payload): array
{
    requireArea($pdo,$user,['ALMACEN']);
    $line=findOne($pdo,"SELECT al.id,al.appointment_id,al.item_id,al.destination_warehouse_id,al.uom_id,al.expected_qty,al.received_qty,a.appointment_number,a.supplier_id,a.origin_id,s.short_code,o.origin_code,i.sku,i.name,i.item_type,u.code AS uom_code FROM inbound_appointment_lines al INNER JOIN inbound_appointments a ON a.id=al.appointment_id INNER JOIN suppliers s ON s.id=a.supplier_id INNER JOIN supplier_origins o ON o.id=a.origin_id INNER JOIN items i ON i.id=al.item_id INNER JOIN units_of_measure u ON u.id=al.uom_id WHERE al.id=:line AND al.line_status IN ('EXPECTED','PARTIALLY_RECEIVED') AND a.status NOT IN ('COMPLETED','CANCELLED','NO_SHOW')",['line'=>(int)($payload['appointment_line_id']??0)],'Selecciona una partida WID pendiente.');
    requireAnyPermissionV14($pdo,(int)$user['id'],[itemModuleV14($line['item_type']),'RECEIVING'],'CREATE');
    $location=findOne($pdo,"SELECT id,location_type FROM warehouse_locations WHERE id=:location AND warehouse_id=:warehouse AND is_active=1",['location'=>(int)($payload['location_id']??0),'warehouse'=>$line['destination_warehouse_id']],'Selecciona una ubicación de recibo o cuarentena del almacén destino.');
    if(!in_array($location['location_type'],['RECEIVING','QUALITY_HOLD'],true))failRequest('La recepción debe entrar a una ubicación de recibo o cuarentena.',422);
    $received=positiveNumber($payload,'received_qty','La cantidad recibida');$remaining=max(0,(float)$line['expected_qty']-(float)$line['received_qty']);
    $date=(new DateTimeImmutable('now',new DateTimeZone('America/Mexico_City')))->format('Y-m-d');
    $pdo->beginTransaction();
    try{
        $prelotRows=safeRows($pdo,"SELECT id,prelot_code FROM pre_lots WHERE appointment_id=:appointment AND status<>'CANCELLED' ORDER BY id LIMIT 1 FOR UPDATE",['appointment'=>$line['appointment_id']]);
        if($prelotRows){$prelotId=(int)$prelotRows[0]['id'];$base=(string)$prelotRows[0]['prelot_code'];}
        else{$prelot=reservePrelotV14($pdo,$line,(int)$line['appointment_id'],$date,(int)$user['id']);$prelotId=(int)$prelot['id'];$base=(string)$prelot['code'];}
        $lotCode=$base;$suffix=1;while(safeScalar($pdo,"SELECT COUNT(*) FROM inventory_lots WHERE item_id=:item AND lot_code=:lot",['item'=>$line['item_id'],'lot'=>$lotCode])>0)$lotCode=$base.'-'.str_pad((string)++$suffix,2,'0',STR_PAD_LEFT);
        $pdo->prepare("UPDATE pre_lots SET status='RECEIVED',confirmed_at=COALESCE(confirmed_at,UTC_TIMESTAMP(6)) WHERE id=:id")->execute(['id'=>$prelotId]);
        $pdo->prepare("INSERT INTO inventory_lots (item_id,lot_code,prelot_id,supplier_id,origin_id,received_date,quality_status,lot_status,created_by) VALUES (:item,:lot,:prelot,:supplier,:origin,:received,'PENDING','BLOCKED',:user)")->execute(['item'=>$line['item_id'],'lot'=>$lotCode,'prelot'=>$prelotId,'supplier'=>$line['supplier_id'],'origin'=>$line['origin_id'],'received'=>$date,'user'=>$user['id']]);$lotId=(int)$pdo->lastInsertId();
        $grossWeight=$line['uom_code']==='KG'?$received:null;
        $pdo->prepare("INSERT INTO goods_receipts (receipt_number,appointment_id,prelot_id,supplier_id,warehouse_id,arrived_at,gross_weight_kg,tare_weight_kg,status,received_by) VALUES (:number,:appointment,:prelot,:supplier,:warehouse,UTC_TIMESTAMP(6),:gross,0,'WAITING_QUALITY',:user)")->execute(['number'=>provisionalNumber('REC'),'appointment'=>$line['appointment_id'],'prelot'=>$prelotId,'supplier'=>$line['supplier_id'],'warehouse'=>$line['destination_warehouse_id'],'gross'=>$grossWeight,'user'=>$user['id']]);$receiptId=(int)$pdo->lastInsertId();$receiptNumber=finalNumber('REC',$receiptId);$pdo->prepare("UPDATE goods_receipts SET receipt_number=:number WHERE id=:id")->execute(['number'=>$receiptNumber,'id'=>$receiptId]);
        $pdo->prepare("INSERT INTO goods_receipt_lines (receipt_id,line_no,item_id,inventory_lot_id,uom_id,ordered_qty,received_qty,notes) VALUES (:receipt,1,:item,:lot,:uom,:ordered,:received,:notes)")->execute(['receipt'=>$receiptId,'item'=>$line['item_id'],'lot'=>$lotId,'uom'=>$line['uom_id'],'ordered'=>$remaining?:$line['expected_qty'],'received'=>$received,'notes'=>optionalString($payload,'notes',500)]);$receiptLineId=(int)$pdo->lastInsertId();
        $qualityType=$line['item_type']==='RAW_FRUIT'?'INBOUND_FRUIT':'INBOUND_MATERIAL';$pdo->prepare("INSERT INTO quality_requests (request_number,request_type,receipt_line_id,inventory_lot_id,target_type,target_id,requested_by,status) VALUES (:number,:type,:receipt_line,:lot,'GOODS_RECEIPT',:receipt,:user,'REQUESTED')")->execute(['number'=>provisionalNumber('CAL'),'type'=>$qualityType,'receipt_line'=>$receiptLineId,'lot'=>$lotId,'receipt'=>$receiptId,'user'=>$user['id']]);$qualityId=(int)$pdo->lastInsertId();$qualityNumber=finalNumber('CAL',$qualityId);$pdo->prepare("UPDATE quality_requests SET request_number=:number WHERE id=:id")->execute(['number'=>$qualityNumber,'id'=>$qualityId]);
        $movementId=createInventoryMovementV14($pdo,'RECEIPT','goods_receipt',$receiptId,$receiptNumber,'Recepción física pendiente de Calidad',(int)$user['id'],[['item_id'=>(int)$line['item_id'],'lot_id'=>$lotId,'warehouse_id'=>(int)$line['destination_warehouse_id'],'location_id'=>(int)$location['id'],'uom_id'=>(int)$line['uom_id'],'qty'=>$received,'notes'=>'Entrada en cuarentena']]);
        $newReceived=(float)$line['received_qty']+$received;$lineStatus=$newReceived+0.000001>=(float)$line['expected_qty']?'RECEIVED':'PARTIALLY_RECEIVED';$pdo->prepare("UPDATE inbound_appointment_lines SET received_qty=:received,line_status=:status WHERE id=:id")->execute(['received'=>$newReceived,'status'=>$lineStatus,'id'=>$line['id']]);$pdo->prepare("UPDATE inbound_appointments SET actual_arrival_at=COALESCE(actual_arrival_at,UTC_TIMESTAMP(6)),status='IN_INSPECTION' WHERE id=:id")->execute(['id'=>$line['appointment_id']]);
        postMovementV14($pdo,$movementId,(int)$user['id']);writeAudit($pdo,(int)$user['id'],'CREATE','goods_receipt',$receiptId,['receipt_number'=>$receiptNumber,'lot'=>$lotCode,'quality_request'=>$qualityNumber,'wid_status'=>$lineStatus]);$pdo->commit();return ['id'=>$receiptId,'number'=>$receiptNumber,'lot'=>$lotCode,'qualityRequest'=>$qualityNumber];
    }catch(Throwable $error){if($pdo->inTransaction())$pdo->rollBack();throw $error;}
}

function createInventoryMovementV14(PDO $pdo,string $type,string $sourceType,int $sourceId,string $reference,string $reason,int $userId,array $lines): int
{
    $pdo->prepare("INSERT INTO inventory_movements (movement_number,movement_type,source_type,source_id,source_reference,status,movement_at,reason,created_by) VALUES (:number,:type,:source_type,:source_id,:reference,'DRAFT',UTC_TIMESTAMP(6),:reason,:user)")->execute(['number'=>provisionalNumber('MOV'),'type'=>$type,'source_type'=>$sourceType,'source_id'=>$sourceId,'reference'=>$reference,'reason'=>$reason,'user'=>$userId]);$movementId=(int)$pdo->lastInsertId();$number=finalNumber('MOV',$movementId);$pdo->prepare("UPDATE inventory_movements SET movement_number=:number WHERE id=:id")->execute(['number'=>$number,'id'=>$movementId]);
    $insert=$pdo->prepare("INSERT INTO inventory_movement_lines (movement_id,line_no,item_id,inventory_lot_id,warehouse_id,location_id,uom_id,quantity_delta,notes) VALUES (:movement,:line,:item,:lot,:warehouse,:location,:uom,:qty,:notes)");
    foreach(array_values($lines) as $index=>$line)$insert->execute(['movement'=>$movementId,'line'=>$index+1,'item'=>$line['item_id'],'lot'=>$line['lot_id']??null,'warehouse'=>$line['warehouse_id'],'location'=>$line['location_id'],'uom'=>$line['uom_id'],'qty'=>$line['qty'],'notes'=>$line['notes']??null]);return $movementId;
}

function postMovementV14(PDO $pdo,int $movementId,int $userId): void
{
    if(!$pdo->inTransaction())failRequest('No se puede contabilizar un movimiento fuera de la operación protegida.',500);
    $movement=findOne($pdo,"SELECT id,status FROM inventory_movements WHERE id=:movement FOR UPDATE",['movement'=>$movementId],'El movimiento de inventario no existe.');
    if($movement['status']!=='DRAFT')failRequest('El movimiento de inventario ya fue contabilizado o cancelado.',409);
    $lineCount=$pdo->prepare("SELECT COUNT(*) FROM inventory_movement_lines WHERE movement_id=:movement");$lineCount->execute(['movement'=>$movementId]);$lines=(int)$lineCount->fetchColumn();
    if($lines<1)failRequest('El movimiento no contiene partidas.',409);
    $shortageCheck=$pdo->prepare("SELECT COUNT(*) FROM (SELECT nl.item_id,nl.inventory_lot_id,nl.warehouse_id,nl.location_id,COALESCE((SELECT SUM(el.quantity_delta) FROM inventory_movement_lines el INNER JOIN inventory_movements em ON em.id=el.movement_id WHERE em.status='POSTED' AND el.item_id=nl.item_id AND el.inventory_lot_id<=>nl.inventory_lot_id AND el.warehouse_id=nl.warehouse_id AND el.location_id=nl.location_id),0)+SUM(nl.quantity_delta) AS resulting_qty,MAX(i.allow_negative_stock) AS allow_negative_stock FROM inventory_movement_lines nl INNER JOIN items i ON i.id=nl.item_id WHERE nl.movement_id=:movement_id GROUP BY nl.item_id,nl.inventory_lot_id,nl.warehouse_id,nl.location_id HAVING allow_negative_stock=0 AND resulting_qty<0) shortages");$shortageCheck->execute(['movement_id'=>$movementId]);$shortages=(int)$shortageCheck->fetchColumn();
    if($shortages>0)failRequest('La operación produciría existencias negativas. Actualiza la pantalla e inténtalo nuevamente.',409);
    $pdo->exec('SET @inventory_post_context = 1');
    try{$pdo->prepare("UPDATE inventory_movements SET status='POSTED',posted_by=:user,posted_at=UTC_TIMESTAMP(6) WHERE id=:movement")->execute(['user'=>$userId,'movement'=>$movementId]);}
    finally{$pdo->exec('SET @inventory_post_context = NULL');}
    writeAudit($pdo,$userId,'POST','inventory_movement',$movementId,['status'=>'POSTED']);
}

function createProductionOrderV14(PDO $pdo,array $user,array $payload): array
{
    requireArea($pdo,$user,['ENVASADO','PRODUCCION']);requireAnyPermissionV14($pdo,(int)$user['id'],['FILLING','PRODUCTION'],'CREATE');
    $bom=findOne($pdo,"SELECT bv.id,bv.output_qty,b.output_item_id,i.name,i.base_uom_id FROM bom_versions bv INNER JOIN bills_of_material b ON b.id=bv.bom_id INNER JOIN items i ON i.id=b.output_item_id WHERE bv.id=:version AND bv.status='ACTIVE' AND b.is_active=1",['version'=>(int)($payload['bom_version_id']??0)],'Selecciona una lista de materiales activa.');
    $qty=positiveNumber($payload,'planned_qty','La cantidad planeada');try{$start=new DateTimeImmutable(requiredString($payload,'planned_start','la fecha de inicio'),new DateTimeZone('America/Mexico_City'));$end=new DateTimeImmutable(requiredString($payload,'planned_end','la fecha de fin'),new DateTimeZone('America/Mexico_City'));}catch(Throwable){failRequest('La ventana de producción no es válida.',422);}if($end<$start)failRequest('La fecha final debe ser posterior a la inicial.',422);
    $shortages=productionShortagesV14($pdo,(int)$bom['id'],$qty);$status=$shortages?'MATERIAL_CHECK':'RELEASED';$customerId=(int)($payload['customer_id']??0)?:null;
    $pdo->beginTransaction();$pdo->prepare("INSERT INTO production_orders (order_number,finished_item_id,bom_version_id,customer_id,planned_qty,uom_id,planned_start,planned_end,status,created_by) VALUES (:number,:item,:bom,:customer,:qty,:uom,:start,:end,:status,:user)")->execute(['number'=>provisionalNumber('OP'),'item'=>$bom['output_item_id'],'bom'=>$bom['id'],'customer'=>$customerId,'qty'=>$qty,'uom'=>$bom['base_uom_id'],'start'=>$start->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s'),'end'=>$end->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s'),'status'=>$status,'user'=>$user['id']]);$id=(int)$pdo->lastInsertId();$number=finalNumber('OP',$id);$pdo->prepare("UPDATE production_orders SET order_number=:number WHERE id=:id")->execute(['number'=>$number,'id'=>$id]);writeAudit($pdo,(int)$user['id'],'CREATE','production_order',$id,['order_number'=>$number,'material_status'=>$status,'shortages'=>$shortages]);$pdo->commit();return ['id'=>$id,'number'=>$number,'status'=>$status,'shortages'=>$shortages];
}

function productionShortagesV14(PDO $pdo,int $bomVersionId,float $outputQty): array
{
    $rows=safeRows($pdo,"SELECT c.component_item_id,i.name,i.sku,(c.qty_per_output*(1+c.scrap_pct/100)/bv.output_qty)*:output_qty AS required_qty,COALESCE(stock.available_qty,0) AS available_qty,u.name AS uom FROM bom_components c INNER JOIN bom_versions bv ON bv.id=c.bom_version_id INNER JOIN items i ON i.id=c.component_item_id INNER JOIN units_of_measure u ON u.id=c.component_uom_id LEFT JOIN (SELECT item_id,SUM(available_qty) AS available_qty FROM vw_inventory_availability GROUP BY item_id) stock ON stock.item_id=c.component_item_id WHERE c.bom_version_id=:version",['output_qty'=>$outputQty,'version'=>$bomVersionId]);return array_values(array_filter($rows,fn($row)=>(float)$row['available_qty']+0.000001<(float)$row['required_qty']));
}

function createProductionCompletionV14(PDO $pdo,array $user,array $payload): array
{
    requireArea($pdo,$user,['ALMACEN','ENVASADO','PRODUCCION']);requireAnyPermissionV14($pdo,(int)$user['id'],['WAREHOUSE_FINISHED','FILLING','PRODUCTION'],'POST');
    $qty=positiveNumber($payload,'completed_qty','La cantidad terminada');
    $pdo->beginTransaction();
    try{
        $order=findOne($pdo,"SELECT o.id,o.order_number,o.finished_item_id,o.bom_version_id,o.planned_qty,o.completed_qty,o.uom_id,i.name,i.sku,i.quality_required FROM production_orders o INNER JOIN items i ON i.id=o.finished_item_id WHERE o.id=:order AND o.status NOT IN ('COMPLETED','CLOSED','CANCELLED') FOR UPDATE",['order'=>(int)($payload['production_order_id']??0)],'Selecciona una orden de producción abierta.');
        if((float)$order['completed_qty']+$qty>(float)$order['planned_qty']+0.000001)failRequest('La cantidad terminada supera lo pendiente de la orden.',422);
        $location=findOne($pdo,"SELECT l.id,w.id AS warehouse_id FROM warehouse_locations l INNER JOIN warehouses w ON w.id=l.warehouse_id WHERE l.id=:location AND w.warehouse_type='FINISHED_GOODS' AND l.location_type IN ('STORAGE','RECEIVING','PRODUCTION') AND l.is_active=1 AND l.is_blocked=0",['location'=>(int)($payload['output_location_id']??0)],'Selecciona una ubicación activa de producto terminado.');
        $components=safeRows($pdo,"SELECT c.component_item_id,c.component_uom_id,c.qty_per_output,c.scrap_pct,bv.output_qty,i.name,i.sku FROM bom_components c INNER JOIN bom_versions bv ON bv.id=c.bom_version_id INNER JOIN items i ON i.id=c.component_item_id WHERE c.bom_version_id=:version ORDER BY c.line_no",['version'=>$order['bom_version_id']]);
        if(!$components)failRequest('La lista de materiales no tiene componentes.',409);
        $wasteInput=[];foreach(($payload['waste_lines']??[]) as $entry)if(is_array($entry))$wasteInput[(int)($entry['component_item_id']??0)]=max(0,(float)($entry['waste_qty']??0));
        $movementLines=[];$materialRows=[];
        foreach($components as $component){
            $planned=$qty/(float)$component['output_qty']*(float)$component['qty_per_output']*(1+(float)$component['scrap_pct']/100);$waste=$wasteInput[(int)$component['component_item_id']]??0.0;$needed=$planned+$waste;
            $lots=safeRows($pdo,"SELECT a.inventory_lot_id,a.warehouse_id,a.location_id,a.uom_id,a.available_qty FROM vw_inventory_availability a LEFT JOIN inventory_lots l ON l.id=a.inventory_lot_id WHERE a.item_id=:item AND a.available_qty>0 ORDER BY COALESCE(l.expiry_date,'9999-12-31'),COALESCE(l.received_date,'9999-12-31'),a.inventory_lot_id",['item'=>$component['component_item_id']]);
            $remaining=$needed;foreach($lots as $lot){if($remaining<=0.000001)break;$take=min($remaining,(float)$lot['available_qty']);$movementLines[]=['item_id'=>(int)$component['component_item_id'],'lot_id'=>$lot['inventory_lot_id']===null?null:(int)$lot['inventory_lot_id'],'warehouse_id'=>(int)$lot['warehouse_id'],'location_id'=>(int)$lot['location_id'],'uom_id'=>(int)$lot['uom_id'],'qty'=>-$take,'notes'=>'Consumo para '.$order['order_number']];$remaining-=$take;}
            if($remaining>0.000001)failRequest('No hay existencia suficiente de '.$component['name'].'. Faltan '.round($remaining,3).'.',409);
            $materialRows[]=['item_id'=>(int)$component['component_item_id'],'uom_id'=>(int)$component['component_uom_id'],'planned'=>$planned,'consumed'=>$needed,'waste'=>$waste];
        }
        $localDate=(new DateTimeImmutable('now',new DateTimeZone('America/Mexico_City')))->format('ymd');$lotCode=trim((string)($payload['finished_lot_code']??''))?:('PT-'.$localDate.'-'.str_pad((string)$order['id'],4,'0',STR_PAD_LEFT));if(safeScalar($pdo,"SELECT COUNT(*) FROM inventory_lots WHERE item_id=:item AND lot_code=:lot",['item'=>$order['finished_item_id'],'lot'=>$lotCode])>0)failRequest('Ese lote de producto terminado ya existe.',409);
        $quality=(int)$order['quality_required']===1?'PENDING':'APPROVED';$lotStatus=$quality==='PENDING'?'BLOCKED':'OPEN';$pdo->prepare("INSERT INTO inventory_lots (item_id,lot_code,manufacture_date,quality_status,lot_status,created_by) VALUES (:item,:lot,CURDATE(),:quality,:status,:user)")->execute(['item'=>$order['finished_item_id'],'lot'=>$lotCode,'quality'=>$quality,'status'=>$lotStatus,'user'=>$user['id']]);$lotId=(int)$pdo->lastInsertId();
        $movementLines[]=['item_id'=>(int)$order['finished_item_id'],'lot_id'=>$lotId,'warehouse_id'=>(int)$location['warehouse_id'],'location_id'=>(int)$location['id'],'uom_id'=>(int)$order['uom_id'],'qty'=>$qty,'notes'=>'Entrada de producto terminado'];
        $movementId=createInventoryMovementV14($pdo,'PRODUCTION_OUTPUT','production_order',(int)$order['id'],$order['order_number'],'Consumo por lista de materiales y entrada de producto terminado',(int)$user['id'],$movementLines);
        $pdo->prepare("INSERT INTO production_completions (production_order_id,completion_number,bom_version_id,finished_lot_id,output_location_id,completed_qty,movement_id,observations,completed_by) VALUES (:order,:number,:bom,:lot,:location,:qty,:movement,:observations,:user)")->execute(['order'=>$order['id'],'number'=>provisionalNumber('APT'),'bom'=>$order['bom_version_id'],'lot'=>$lotId,'location'=>$location['id'],'qty'=>$qty,'movement'=>$movementId,'observations'=>optionalString($payload,'observations',1000),'user'=>$user['id']]);$completionId=(int)$pdo->lastInsertId();$number=finalNumber('APT',$completionId);$pdo->prepare("UPDATE production_completions SET completion_number=:number WHERE id=:id")->execute(['number'=>$number,'id'=>$completionId]);
        $relation=$pdo->prepare("INSERT IGNORE INTO lot_relations (parent_lot_id,child_lot_id,relation_type,quantity,reference_type,reference_id) VALUES (:parent,:child,'PACKAGING',:quantity,'production_completion',:completion)");foreach($movementLines as $movementLine)if(($movementLine['lot_id']??null)!==null&&(float)$movementLine['qty']<0)$relation->execute(['parent'=>$movementLine['lot_id'],'child'=>$lotId,'quantity'=>abs((float)$movementLine['qty']),'completion'=>$completionId]);
        $insert=$pdo->prepare("INSERT INTO production_completion_materials (production_completion_id,component_item_id,planned_qty,consumed_qty,waste_qty,uom_id) VALUES (:completion,:item,:planned,:consumed,:waste,:uom)");foreach($materialRows as $row)$insert->execute(['completion'=>$completionId,'item'=>$row['item_id'],'planned'=>$row['planned'],'consumed'=>$row['consumed'],'waste'=>$row['waste'],'uom'=>$row['uom_id']]);
        $completed=(float)$order['completed_qty']+$qty;$status=$completed+0.000001>=(float)$order['planned_qty']?'COMPLETED':'IN_PROCESS';$pdo->prepare("UPDATE production_orders SET completed_qty=:completed,status=:status,actual_start=COALESCE(actual_start,UTC_TIMESTAMP(6)),actual_end=CASE WHEN :status_end='COMPLETED' THEN UTC_TIMESTAMP(6) ELSE actual_end END WHERE id=:id")->execute(['completed'=>$completed,'status'=>$status,'status_end'=>$status,'id'=>$order['id']]);
        $qualityRequest=null;if($quality==='PENDING'){$pdo->prepare("INSERT INTO quality_requests (request_number,request_type,inventory_lot_id,target_type,target_id,requested_by,status) VALUES (:number,'FINISHED_GOOD',:lot,'PRODUCTION_COMPLETION',:completion,:user,'REQUESTED')")->execute(['number'=>provisionalNumber('CAL'),'lot'=>$lotId,'completion'=>$completionId,'user'=>$user['id']]);$qualityId=(int)$pdo->lastInsertId();$qualityRequest=finalNumber('CAL',$qualityId);$pdo->prepare("UPDATE quality_requests SET request_number=:number WHERE id=:id")->execute(['number'=>$qualityRequest,'id'=>$qualityId]);}
        postMovementV14($pdo,$movementId,(int)$user['id']);writeAudit($pdo,(int)$user['id'],'POST','production_completion',$completionId,['completion_number'=>$number,'order'=>$order['order_number'],'lot'=>$lotCode,'quality_request'=>$qualityRequest]);$pdo->commit();return ['id'=>$completionId,'number'=>$number,'lot'=>$lotCode,'qualityRequest'=>$qualityRequest];
    }catch(Throwable $error){if($pdo->inTransaction())$pdo->rollBack();throw $error;}
}

function createExtractionV14(PDO $pdo,array $user,array $payload): array
{
    requireArea($pdo,$user,['EXTRACCION']);requirePermission($pdo,(int)$user['id'],'EXTRACTION','POST');
    $source=findOne($pdo,"SELECT a.item_id,a.inventory_lot_id,a.warehouse_id,a.location_id,a.uom_id,a.available_qty,i.name,i.item_type,l.lot_code FROM vw_inventory_availability a INNER JOIN items i ON i.id=a.item_id INNER JOIN inventory_lots l ON l.id=a.inventory_lot_id WHERE a.inventory_lot_id=:lot AND a.location_id=:location AND a.available_qty>0 AND i.item_type='RAW_FRUIT'",['lot'=>(int)($payload['source_lot_id']??0),'location'=>(int)($payload['source_location_id']??0)],'Selecciona un lote de aguacate disponible.');$qty=positiveNumber($payload,'input_qty','La cantidad alimentada');if($qty>(float)$source['available_qty']+0.000001)failRequest('La cantidad supera la existencia disponible del lote.',409);
    $output=findOne($pdo,"SELECT id,name,base_uom_id FROM items WHERE id=:item AND item_type='BULK_OIL' AND is_active=1",['item'=>(int)($payload['output_item_id']??0)],'Selecciona el aceite crudo de salida.');$outputLocation=findOne($pdo,"SELECT l.id,w.id AS warehouse_id FROM warehouse_locations l INNER JOIN warehouses w ON w.id=l.warehouse_id WHERE l.id=:location AND w.warehouse_type IN ('PROCESS','RAW_MATERIAL') AND l.is_active=1",['location'=>(int)($payload['output_location_id']??0)],'Selecciona una ubicación de proceso para el aceite.');$beans=(int)($payload['beans_count']??0);$hours=(float)($payload['operating_hours']??0);if($beans<1||$hours<=0)failRequest('Indica los contenedores y las horas reales.',422);$shift=requiredString($payload,'shift_code','el turno',30);
    $pdo->beginTransaction();try{$pdo->prepare("INSERT INTO process_batches (batch_code,process_type,status,started_at,shift_code,target_beans_hour,actual_beans,created_by) VALUES (:code,'EXTRACTION','IN_PROCESS',UTC_TIMESTAMP(6),:shift,13,:beans,:user)")->execute(['code'=>provisionalNumber('EXT'),'shift'=>$shift,'beans'=>$beans,'user'=>$user['id']]);$batchId=(int)$pdo->lastInsertId();$localDate=(new DateTimeImmutable('now',new DateTimeZone('America/Mexico_City')))->format('ymd');$batchCode='EXT-'.$localDate.'-'.str_pad((string)$batchId,4,'0',STR_PAD_LEFT);$pdo->prepare("UPDATE process_batches SET batch_code=:code WHERE id=:id")->execute(['code'=>$batchCode,'id'=>$batchId]);$pdo->prepare("INSERT INTO inventory_lots (item_id,lot_code,manufacture_date,quality_status,lot_status,created_by) VALUES (:item,:lot,CURDATE(),'PENDING','BLOCKED',:user)")->execute(['item'=>$output['id'],'lot'=>$batchCode,'user'=>$user['id']]);$outputLotId=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO process_batch_inputs (process_batch_id,line_no,item_id,inventory_lot_id,uom_id,actual_qty,fed_at,recorded_by) VALUES (:batch,1,:item,:lot,:uom,:qty,UTC_TIMESTAMP(6),:user)")->execute(['batch'=>$batchId,'item'=>$source['item_id'],'lot'=>$source['inventory_lot_id'],'uom'=>$source['uom_id'],'qty'=>$qty,'user'=>$user['id']]);$pdo->prepare("INSERT INTO lot_genealogy (process_batch_id,parent_lot_id,child_lot_id,parent_qty_used,contribution_pct) VALUES (:batch,:parent,:child,:qty,100)")->execute(['batch'=>$batchId,'parent'=>$source['inventory_lot_id'],'child'=>$outputLotId,'qty'=>$qty]);$pdo->prepare("INSERT IGNORE INTO lot_relations (parent_lot_id,child_lot_id,relation_type,quantity,reference_type,reference_id) VALUES (:parent,:child,'EXTRACTION',:qty,'process_batch',:batch)")->execute(['parent'=>$source['inventory_lot_id'],'child'=>$outputLotId,'qty'=>$qty,'batch'=>$batchId]);$pdo->prepare("INSERT INTO extraction_runs (process_batch_id,source_location_id,output_location_id,output_lot_id,beans_count,operating_hours,target_beans_hour,created_by) VALUES (:batch,:source_location,:output_location,:output_lot,:beans,:hours,13,:user)")->execute(['batch'=>$batchId,'source_location'=>$source['location_id'],'output_location'=>$outputLocation['id'],'output_lot'=>$outputLotId,'beans'=>$beans,'hours'=>$hours,'user'=>$user['id']]);$movementId=createInventoryMovementV14($pdo,'ISSUE_PRODUCTION','process_batch',$batchId,$batchCode,'Alimentación de aguacate a extracción',(int)$user['id'],[['item_id'=>(int)$source['item_id'],'lot_id'=>(int)$source['inventory_lot_id'],'warehouse_id'=>(int)$source['warehouse_id'],'location_id'=>(int)$source['location_id'],'uom_id'=>(int)$source['uom_id'],'qty'=>-$qty,'notes'=>'Lote de origen '.$source['lot_code']]]);$pdo->prepare("INSERT INTO quality_requests (request_number,request_type,inventory_lot_id,target_type,target_id,requested_by,status) VALUES (:number,'IN_PROCESS',:lot,'EXTRACTION_BATCH',:batch,:user,'REQUESTED')")->execute(['number'=>provisionalNumber('CAL'),'lot'=>$outputLotId,'batch'=>$batchId,'user'=>$user['id']]);$qualityId=(int)$pdo->lastInsertId();$qualityNumber=finalNumber('CAL',$qualityId);$pdo->prepare("UPDATE quality_requests SET request_number=:number WHERE id=:id")->execute(['number'=>$qualityNumber,'id'=>$qualityId]);postMovementV14($pdo,$movementId,(int)$user['id']);writeAudit($pdo,(int)$user['id'],'POST','process_batch',$batchId,['batch_code'=>$batchCode,'source_lot'=>$source['lot_code'],'beans'=>$beans,'actual_beans_hour'=>$beans/$hours,'quality_request'=>$qualityNumber]);$pdo->commit();return ['id'=>$batchId,'batchCode'=>$batchCode,'qualityRequest'=>$qualityNumber,'actualBeansHour'=>round($beans/$hours,2)];}catch(Throwable $error){if($pdo->inTransaction())$pdo->rollBack();throw $error;}
}

function saveQualityDecisionV14(PDO $pdo,array $user,array $payload): array
{
    requireArea($pdo,$user,['CALIDAD']);$disposition=strtoupper(requiredString($payload,'disposition','el dictamen',25));if(!in_array($disposition,['APPROVED','CONDITIONAL','REJECTED'],true))failRequest('El dictamen no es válido.',422);requirePermission($pdo,(int)$user['id'],'QUALITY',$disposition==='REJECTED'?'REJECT':'APPROVE');
    $request=findOne($pdo,"SELECT q.id,q.request_number,q.request_type,q.inventory_lot_id,q.target_type,q.target_id,q.status,l.item_id,l.lot_code,i.item_type,i.base_uom_id,rl.id AS receipt_line_id,rl.receipt_id,COALESCE(rl.received_qty,pc.completed_qty,0) AS received_qty,COALESCE(r.warehouse_id,pcl.warehouse_id) AS warehouse_id FROM quality_requests q LEFT JOIN inventory_lots l ON l.id=q.inventory_lot_id LEFT JOIN items i ON i.id=l.item_id LEFT JOIN goods_receipt_lines rl ON rl.id=q.receipt_line_id LEFT JOIN goods_receipts r ON r.id=rl.receipt_id LEFT JOIN production_completions pc ON q.target_type='PRODUCTION_COMPLETION' AND pc.id=q.target_id LEFT JOIN warehouse_locations pcl ON pcl.id=pc.output_location_id WHERE q.id=:request",['request'=>(int)($payload['quality_request_id']??0)],'La solicitud de Calidad no existe.');if(in_array($request['status'],['COMPLETED','CANCELLED'],true))failRequest('La solicitud ya está cerrada.',409);
    $reason=requiredString($payload,'reason','las observaciones del dictamen',1000);$received=(float)($request['received_qty']??0);if($request['request_type']==='IN_PROCESS')$received=(float)($payload['oil_obtained_qty']??0);if($received<=0)failRequest('La cantidad a dictaminar debe ser mayor que cero.',422);$accepted=(float)($payload['accepted_qty']??($disposition==='REJECTED'?0:$received));$rejected=(float)($payload['rejected_qty']??($disposition==='REJECTED'?$received:0));if($accepted<0||$rejected<0||abs(($accepted+$rejected)-$received)>0.0001)failRequest('La cantidad liberada más la rechazada debe coincidir con la cantidad recibida o producida.',422);if($disposition==='REJECTED'&&$accepted>0)failRequest('Un dictamen rechazado no puede liberar cantidad.',422);if($disposition==='APPROVED'&&$rejected>0)failRequest('Si existe cantidad rechazada, selecciona el dictamen parcial o condicional.',422);
    $acceptedLocationId=$accepted>0?(int)($payload['accepted_location_id']??0):null;$rejectedLocationId=$rejected>0?(int)($payload['rejected_location_id']??0):null;if($accepted>0)$acceptedLocation=findOne($pdo,"SELECT l.id,w.id AS warehouse_id,w.warehouse_type FROM warehouse_locations l INNER JOIN warehouses w ON w.id=l.warehouse_id WHERE l.id=:location AND l.is_active=1 AND l.is_blocked=0 AND l.location_type IN ('STORAGE','PRODUCTION','PICKING')",['location'=>$acceptedLocationId],'Selecciona una ubicación disponible para la cantidad liberada.');if($rejected>0)$rejectedLocation=findOne($pdo,"SELECT l.id,w.id AS warehouse_id,w.warehouse_type FROM warehouse_locations l INNER JOIN warehouses w ON w.id=l.warehouse_id WHERE l.id=:location AND l.is_active=1 AND l.location_type='REJECTED'",['location'=>$rejectedLocationId],'Selecciona una ubicación de rechazados.');
    if($accepted>0&&$request['request_type']!=='IN_PROCESS'&&(int)$acceptedLocation['warehouse_id']!==(int)$request['warehouse_id'])failRequest('La cantidad liberada debe permanecer en el almacén que recibió o produjo el material.',422);
    if($rejected>0&&$request['request_type']!=='IN_PROCESS'&&(int)$rejectedLocation['warehouse_id']!==(int)$request['warehouse_id'])failRequest('La cantidad rechazada debe quedar en el área de rechazados del almacén que recibió o produjo el material.',422);
    if($accepted>0&&$request['request_type']==='IN_PROCESS'&&!in_array($acceptedLocation['warehouse_type'],['RAW_MATERIAL','PROCESS'],true))failRequest('El aceite de extracción debe liberarse a una ubicación de materia prima o proceso.',422);
    if($rejected>0&&$request['request_type']==='IN_PROCESS'&&!in_array($rejectedLocation['warehouse_type'],['RAW_MATERIAL','PROCESS'],true))failRequest('El aceite rechazado de extracción debe aislarse en materia prima o proceso.',422);
    $pdo->beginTransaction();try{
        saveQualityAnalyticsV14($pdo,$user,$request,$payload);
        $acceptedLotId=null;$rejectedLotId=null;$movementLines=[];
        if($request['request_type']==='IN_PROCESS'){
            if($accepted>0){$acceptedLotId=(int)$request['inventory_lot_id'];$pdo->prepare("UPDATE inventory_lots SET quality_status=:quality,lot_status='OPEN' WHERE id=:id")->execute(['quality'=>$disposition,'id'=>$acceptedLotId]);$movementLines[]=['item_id'=>(int)$request['item_id'],'lot_id'=>$acceptedLotId,'warehouse_id'=>(int)$acceptedLocation['warehouse_id'],'location_id'=>(int)$acceptedLocation['id'],'uom_id'=>(int)$request['base_uom_id'],'qty'=>$accepted,'notes'=>'Aceite obtenido liberado por Calidad'];}
            if($rejected>0){$rejectedLotId=createChildLotV14($pdo,$request,'-REC','REJECTED',(int)$user['id']);$movementLines[]=['item_id'=>(int)$request['item_id'],'lot_id'=>$rejectedLotId,'warehouse_id'=>(int)$rejectedLocation['warehouse_id'],'location_id'=>(int)$rejectedLocation['id'],'uom_id'=>(int)$request['base_uom_id'],'qty'=>$rejected,'notes'=>'Aceite obtenido rechazado por Calidad'];}
            $outputInsert=$pdo->prepare("INSERT INTO process_batch_outputs (process_batch_id,line_no,item_id,inventory_lot_id,uom_id,output_qty,output_type,recorded_by) VALUES (:batch,:line,:item,:lot,:uom,:qty,:type,:user)");$outputLine=0;if($accepted>0)$outputInsert->execute(['batch'=>$request['target_id'],'line'=>++$outputLine,'item'=>$request['item_id'],'lot'=>$acceptedLotId,'uom'=>$request['base_uom_id'],'qty'=>$accepted,'type'=>'PRIMARY','user'=>$user['id']]);if($rejected>0)$outputInsert->execute(['batch'=>$request['target_id'],'line'=>++$outputLine,'item'=>$request['item_id'],'lot'=>$rejectedLotId,'uom'=>$request['base_uom_id'],'qty'=>$rejected,'type'=>'WASTE','user'=>$user['id']]);$pdo->prepare("UPDATE process_batches SET status='COMPLETED',completed_at=UTC_TIMESTAMP(6) WHERE id=:id")->execute(['id'=>$request['target_id']]);
        }else{
            $source=safeRows($pdo,"SELECT item_id,inventory_lot_id,warehouse_id,location_id,uom_id,on_hand_qty FROM vw_inventory_on_hand WHERE inventory_lot_id=:lot AND on_hand_qty>0 ORDER BY on_hand_qty DESC LIMIT 1",['lot'=>$request['inventory_lot_id']]);if(!$source)failRequest('No se encontró la existencia en cuarentena asociada a esta solicitud.',409);$source=$source[0];if((float)$source['on_hand_qty']+0.000001<$received)failRequest('La existencia del lote ya no coincide con la cantidad pendiente de dictamen.',409);$movementLines[]=['item_id'=>(int)$source['item_id'],'lot_id'=>(int)$source['inventory_lot_id'],'warehouse_id'=>(int)$source['warehouse_id'],'location_id'=>(int)$source['location_id'],'uom_id'=>(int)$source['uom_id'],'qty'=>-$received,'notes'=>'Salida de cuarentena por dictamen'];
            $partial=$accepted>0&&$rejected>0;if($accepted>0){$acceptedLotId=$partial?createChildLotV14($pdo,$request,'-LIB',$disposition,(int)$user['id']):(int)$request['inventory_lot_id'];$movementLines[]=['item_id'=>(int)$source['item_id'],'lot_id'=>$acceptedLotId,'warehouse_id'=>(int)$acceptedLocation['warehouse_id'],'location_id'=>(int)$acceptedLocation['id'],'uom_id'=>(int)$source['uom_id'],'qty'=>$accepted,'notes'=>'Cantidad liberada por Calidad'];}if($rejected>0){$rejectedLotId=$partial?createChildLotV14($pdo,$request,'-REC','REJECTED',(int)$user['id']):(int)$request['inventory_lot_id'];$movementLines[]=['item_id'=>(int)$source['item_id'],'lot_id'=>$rejectedLotId,'warehouse_id'=>(int)$rejectedLocation['warehouse_id'],'location_id'=>(int)$rejectedLocation['id'],'uom_id'=>(int)$source['uom_id'],'qty'=>$rejected,'notes'=>'Cantidad rechazada por Calidad'];}if($partial)$pdo->prepare("UPDATE inventory_lots SET quality_status='CONDITIONAL',lot_status='CONSUMED' WHERE id=:id")->execute(['id'=>$request['inventory_lot_id']]);else $pdo->prepare("UPDATE inventory_lots SET quality_status=:quality,lot_status=:status WHERE id=:id")->execute(['quality'=>$disposition,'status'=>$disposition==='REJECTED'?'BLOCKED':'OPEN','id'=>$request['inventory_lot_id']]);
        }
        $movementId=createInventoryMovementV14($pdo,$accepted>0?'QUALITY_RELEASE':'QUALITY_REJECT','quality_request',(int)$request['id'],$request['request_number'],$reason,(int)$user['id'],$movementLines);$pdo->prepare("UPDATE quality_requests SET status='COMPLETED',disposition=:disposition,disposition_reason=:reason,completed_at=UTC_TIMESTAMP(6),decided_by=:user,decided_at=UTC_TIMESTAMP(6) WHERE id=:id")->execute(['disposition'=>$disposition,'reason'=>$reason,'user'=>$user['id'],'id'=>$request['id']]);$pdo->prepare("INSERT INTO quality_status_history (quality_request_id,from_status,to_status,notes,changed_by) VALUES (:request,:from,'COMPLETED',:notes,:user)")->execute(['request'=>$request['id'],'from'=>$request['status'],'notes'=>mb_substr($reason,0,500),'user'=>$user['id']]);$pdo->prepare("INSERT INTO quality_dispositions (quality_request_id,received_qty,accepted_qty,rejected_qty,uom_id,accepted_lot_id,rejected_lot_id,accepted_location_id,rejected_location_id,observations,decided_by) VALUES (:request,:received,:accepted,:rejected,:uom,:accepted_lot,:rejected_lot,:accepted_location,:rejected_location,:observations,:user)")->execute(['request'=>$request['id'],'received'=>$received,'accepted'=>$accepted,'rejected'=>$rejected,'uom'=>$request['base_uom_id'],'accepted_lot'=>$acceptedLotId,'rejected_lot'=>$rejectedLotId,'accepted_location'=>$acceptedLocationId,'rejected_location'=>$rejectedLocationId,'observations'=>$reason,'user'=>$user['id']]);if($request['receipt_line_id'])$pdo->prepare("UPDATE goods_receipt_lines SET accepted_qty=:accepted,rejected_qty=:rejected WHERE id=:id")->execute(['accepted'=>$accepted,'rejected'=>$rejected,'id'=>$request['receipt_line_id']]);if($request['receipt_id']){$receiptStatus=$accepted>0&&$rejected>0?'PARTIALLY_ACCEPTED':($accepted>0?'ACCEPTED':'REJECTED');$pdo->prepare("UPDATE goods_receipts SET status=:status WHERE id=:id")->execute(['status'=>$receiptStatus,'id'=>$request['receipt_id']]);}postMovementV14($pdo,$movementId,(int)$user['id']);writeAudit($pdo,(int)$user['id'],$accepted>0?'APPROVE':'REJECT','quality_request',$request['id'],['accepted_qty'=>$accepted,'rejected_qty'=>$rejected,'movement_id'=>$movementId],$reason);$pdo->commit();return ['id'=>(int)$request['id'],'acceptedQty'=>$accepted,'rejectedQty'=>$rejected];
    }catch(Throwable $error){if($pdo->inTransaction())$pdo->rollBack();throw $error;}
}

function createChildLotV14(PDO $pdo,array $request,string $suffix,string $quality,int $userId): int
{
    $base=substr((string)$request['lot_code'],0,88).$suffix;$code=$base;$index=1;while(safeScalar($pdo,"SELECT COUNT(*) FROM inventory_lots WHERE item_id=:item AND lot_code=:lot",['item'=>$request['item_id'],'lot'=>$code])>0)$code=substr($base,0,95).'-'.++$index;$status=$quality==='REJECTED'?'BLOCKED':'OPEN';$pdo->prepare("INSERT INTO inventory_lots (item_id,lot_code,prelot_id,supplier_id,origin_id,supplier_lot_code,manufacture_date,received_date,expiry_date,quality_status,lot_status,attributes_json,created_by) SELECT item_id,:code,prelot_id,supplier_id,origin_id,supplier_lot_code,manufacture_date,received_date,expiry_date,:quality,:status,attributes_json,:user FROM inventory_lots WHERE id=:parent")->execute(['code'=>$code,'quality'=>$quality,'status'=>$status,'user'=>$userId,'parent'=>$request['inventory_lot_id']]);$id=(int)$pdo->lastInsertId();$pdo->prepare("INSERT IGNORE INTO lot_relations (parent_lot_id,child_lot_id,relation_type,reference_type,reference_id) VALUES (:parent,:child,'QUALITY_SPLIT','quality_request',:request)")->execute(['parent'=>$request['inventory_lot_id'],'child'=>$id,'request'=>$request['id']]);return $id;
}

function saveQualityAnalyticsV14(PDO $pdo,array $user,array $request,array $payload): void
{
    $nullableNumber=static function(array $data,string $key): ?float {$value=trim((string)($data[$key]??''));if($value==='')return null;if(!is_numeric($value))failRequest('Uno de los resultados numéricos no es válido.',422);return (float)$value;};
    $date=validDate((string)($payload['sample_date']??date('Y-m-d')));$week=(int)($payload['week_number']??date('W'));if($week<1||$week>53)failRequest('La semana debe estar entre 1 y 53.',422);
    if($request['request_type']==='INBOUND_FRUIT'){$endDate=trim((string)($payload['process_end_date']??''));if($endDate!=='')$endDate=validDate($endDate);else $endDate=null;$pdo->prepare("INSERT INTO raw_material_quality_results (quality_request_id,week_number,sample_date,quantity_kg,dry_matter_equipment_pct,dry_matter_avocado_pulp_pct,dry_matter_pulp_method_pct,firmness_pa,avocado_yield_soxhlet_pct,pulp_yield_soxhlet_pct,free_fatty_acids_pct,fruit_status,process_end_date,extracted_oil_qty,acidity_pct,observations,recorded_by) VALUES (:request,:week,:date,:quantity,:dry_equipment,:dry_avocado,:dry_pulp,:firmness,:avocado_yield,:pulp_yield,:ffa,:fruit_status,:end_date,:oil,:acidity,:observations,:user) ON DUPLICATE KEY UPDATE week_number=VALUES(week_number),sample_date=VALUES(sample_date),quantity_kg=VALUES(quantity_kg),dry_matter_equipment_pct=VALUES(dry_matter_equipment_pct),dry_matter_avocado_pulp_pct=VALUES(dry_matter_avocado_pulp_pct),dry_matter_pulp_method_pct=VALUES(dry_matter_pulp_method_pct),firmness_pa=VALUES(firmness_pa),avocado_yield_soxhlet_pct=VALUES(avocado_yield_soxhlet_pct),pulp_yield_soxhlet_pct=VALUES(pulp_yield_soxhlet_pct),free_fatty_acids_pct=VALUES(free_fatty_acids_pct),fruit_status=VALUES(fruit_status),process_end_date=VALUES(process_end_date),extracted_oil_qty=VALUES(extracted_oil_qty),acidity_pct=VALUES(acidity_pct),observations=VALUES(observations),recorded_by=VALUES(recorded_by),recorded_at=UTC_TIMESTAMP(6)")->execute(['request'=>$request['id'],'week'=>$week,'date'=>$date,'quantity'=>$nullableNumber($payload,'quantity_kg'),'dry_equipment'=>$nullableNumber($payload,'dry_matter_equipment_pct'),'dry_avocado'=>$nullableNumber($payload,'dry_matter_avocado_pulp_pct'),'dry_pulp'=>$nullableNumber($payload,'dry_matter_pulp_method_pct'),'firmness'=>$nullableNumber($payload,'firmness_pa'),'avocado_yield'=>$nullableNumber($payload,'avocado_yield_soxhlet_pct'),'pulp_yield'=>$nullableNumber($payload,'pulp_yield_soxhlet_pct'),'ffa'=>$nullableNumber($payload,'free_fatty_acids_pct'),'fruit_status'=>optionalString($payload,'fruit_status',30),'end_date'=>$endDate,'oil'=>$nullableNumber($payload,'extracted_oil_qty'),'acidity'=>$nullableNumber($payload,'acidity_pct'),'observations'=>optionalString($payload,'reason',2000),'user'=>$user['id']]);}
    if($request['request_type']==='IN_PROCESS'){$sampleType=strtoupper(requiredString($payload,'sample_type','el tipo de muestra',25));$prefix=['PULP'=>'PU','WET_PASTE'=>'PH','DRY_PASTE'=>'PS'][$sampleType]??null;if(!$prefix)failRequest('El tipo de muestra no es válido.',422);$sampleLot=$prefix.date('dmy',strtotime($date)).'-'.str_pad((string)$request['id'],3,'0',STR_PAD_LEFT);$pdo->prepare("INSERT INTO extraction_quality_results (quality_request_id,process_batch_id,week_number,sample_date,shift_code,equipment_code,sample_type,sample_lot_code,fruit_per_shift_kg,grinding_against_target_pct,oil_wet_basis_pct,oil_dry_basis_pct,oil_in_fruit_pulp_pct,retained_oil_pct,obtaining_against_target_pct,oil_obtained_qty,dry_matter_pct,humidity_pct,humidity_plus_dry_matter_pct,observations,recorded_by) VALUES (:request,:batch,:week,:date,:shift,:equipment,:sample_type,:sample_lot,:fruit,:grinding,:oil_wet,:oil_dry,:oil_fruit,:retained,:obtaining,:oil_obtained,:dry_matter,:humidity,:total,:observations,:user) ON DUPLICATE KEY UPDATE week_number=VALUES(week_number),sample_date=VALUES(sample_date),shift_code=VALUES(shift_code),equipment_code=VALUES(equipment_code),sample_type=VALUES(sample_type),fruit_per_shift_kg=VALUES(fruit_per_shift_kg),grinding_against_target_pct=VALUES(grinding_against_target_pct),oil_wet_basis_pct=VALUES(oil_wet_basis_pct),oil_dry_basis_pct=VALUES(oil_dry_basis_pct),oil_in_fruit_pulp_pct=VALUES(oil_in_fruit_pulp_pct),retained_oil_pct=VALUES(retained_oil_pct),obtaining_against_target_pct=VALUES(obtaining_against_target_pct),oil_obtained_qty=VALUES(oil_obtained_qty),dry_matter_pct=VALUES(dry_matter_pct),humidity_pct=VALUES(humidity_pct),humidity_plus_dry_matter_pct=VALUES(humidity_plus_dry_matter_pct),observations=VALUES(observations),recorded_by=VALUES(recorded_by),recorded_at=UTC_TIMESTAMP(6)")->execute(['request'=>$request['id'],'batch'=>$request['target_id'],'week'=>$week,'date'=>$date,'shift'=>requiredString($payload,'shift_code','el turno',30),'equipment'=>optionalString($payload,'equipment_code',50),'sample_type'=>$sampleType,'sample_lot'=>$sampleLot,'fruit'=>$nullableNumber($payload,'fruit_per_shift_kg'),'grinding'=>$nullableNumber($payload,'grinding_against_target_pct'),'oil_wet'=>$nullableNumber($payload,'oil_wet_basis_pct'),'oil_dry'=>$nullableNumber($payload,'oil_dry_basis_pct'),'oil_fruit'=>$nullableNumber($payload,'oil_in_fruit_pulp_pct'),'retained'=>$nullableNumber($payload,'retained_oil_pct'),'obtaining'=>$nullableNumber($payload,'obtaining_against_target_pct'),'oil_obtained'=>$nullableNumber($payload,'oil_obtained_qty'),'dry_matter'=>$nullableNumber($payload,'dry_matter_pct'),'humidity'=>$nullableNumber($payload,'humidity_pct'),'total'=>$nullableNumber($payload,'humidity_plus_dry_matter_pct'),'observations'=>optionalString($payload,'reason',2000),'user'=>$user['id']]);}
}

function cancelQualityRequestV14(PDO $pdo,array $user,array $payload): array
{
    requireArea($pdo,$user,['CALIDAD']);requirePermission($pdo,(int)$user['id'],'QUALITY','UPDATE');$request=findOne($pdo,"SELECT id,status FROM quality_requests WHERE id=:id",['id'=>(int)($payload['quality_request_id']??0)],'La solicitud no existe.');if(in_array($request['status'],['COMPLETED','CANCELLED'],true))failRequest('La solicitud ya está cerrada.',409);$reason=requiredString($payload,'reason','el motivo de cancelación',500);$pdo->beginTransaction();$pdo->prepare("UPDATE quality_requests SET status='CANCELLED',disposition_reason=:reason,completed_at=UTC_TIMESTAMP(6),decided_by=:user,decided_at=UTC_TIMESTAMP(6) WHERE id=:id")->execute(['reason'=>$reason,'user'=>$user['id'],'id'=>$request['id']]);$pdo->prepare("INSERT INTO quality_status_history (quality_request_id,from_status,to_status,notes,changed_by) VALUES (:request,:from_status,'CANCELLED',:notes,:user)")->execute(['request'=>$request['id'],'from_status'=>$request['status'],'notes'=>$reason,'user'=>$user['id']]);writeAudit($pdo,(int)$user['id'],'UPDATE','quality_request',$request['id'],['status'=>'CANCELLED'],$reason);$pdo->commit();return ['id'=>(int)$request['id'],'status'=>'CANCELLED'];
}

function registerTechnicianV14(PDO $pdo,array $user,array $payload): array
{
    if(!isMaintenanceLeader($pdo,$user))failRequest('Solo el administrador o jefe de Mantenimiento puede registrar técnicos.',403);$candidate=findOne($pdo,"SELECT u.id FROM app_users u INNER JOIN areas a ON a.id=u.primary_area_id WHERE u.id=:user AND u.status='ACTIVE' AND a.code='MANTENIMIENTO'",['user'=>(int)($payload['technician_user_id']??0)],'Selecciona un usuario activo del área de Mantenimiento.');$pdo->prepare("INSERT INTO maintenance_technicians (user_id,specialties,phone,is_active,created_by) VALUES (:technician,:specialties,:phone,1,:creator) ON DUPLICATE KEY UPDATE specialties=VALUES(specialties),phone=VALUES(phone),is_active=1")->execute(['technician'=>$candidate['id'],'specialties'=>optionalString($payload,'specialties',500),'phone'=>optionalString($payload,'phone',40),'creator'=>$user['id']]);writeAudit($pdo,(int)$user['id'],'UPDATE','maintenance_technician',$candidate['id'],['active'=>true]);return ['id'=>(int)$candidate['id']];
}
